content:
Below is an idiomatic Pulumi TypeScript `ComponentResource` that wraps:

- an S3 bucket
- an RDS PostgreSQL instance
- an IAM role for service accounts

It supports `dev`/`prod` via Pulumi stack config and follows your acceptance criteria for the resources in scope.

---

## File: `infra/appPlatform.ts`

```ts
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export interface AppPlatformArgs {
    /**
     * VPC networking for RDS
     */
    subnetIds: pulumi.Input<pulumi.Input<string>[]>;
    vpcSecurityGroupIds: pulumi.Input<pulumi.Input<string>[]>;

    /**
     * Optional: OIDC provider ARN/URL for IRSA-style trust policy.
     * If omitted, a generic role is created with no federated trust policy.
     */
    oidcProviderArn?: pulumi.Input<string>;
    oidcProviderUrl?: pulumi.Input<string>;
    k8sNamespace?: pulumi.Input<string>;
    k8sServiceAccountName?: pulumi.Input<string>;

    /**
     * DB credentials
     */
    dbName?: pulumi.Input<string>;
    dbUsername?: pulumi.Input<string>;
    dbPassword: pulumi.Input<string>;

    /**
     * Optional tagging
     */
    tags?: Record<string, pulumi.Input<string>>;
}

export class AppPlatform extends pulumi.ComponentResource {
    public readonly bucket: aws.s3.BucketV2;
    public readonly db: aws.rds.Instance;
    public readonly iamRole: aws.iam.Role;
    public readonly dbSubnetGroup: aws.rds.SubnetGroup;
    public readonly bucketPolicyBlock: aws.s3.BucketPublicAccessBlock;
    public readonly dbConnectionString: pulumi.Output<string>;

    constructor(name: string, args: AppPlatformArgs, opts?: pulumi.ComponentResourceOptions) {
        super("custom:platform:AppPlatform", name, args, opts);

        const config = new pulumi.Config();
        const stack = pulumi.getStack();

        const environment = config.get("environment") || stack;

        const isProd = environment === "prod";

        const dbInstanceClass = isProd ? "db.t3.medium" : "db.t3.micro";
        const multiAz = isProd;
        const dbAllocatedStorage = isProd ? 50 : 20;
        const backupRetentionPeriod = 7;

        const tags = {
            Environment: environment,
            ManagedBy: "Pulumi",
            Component: name,
            ...(args.tags || {}),
        };

        /**
         * S3 bucket
         * - versioning enabled
         * - encryption enabled
         * - public access blocked
         */
        this.bucket = new aws.s3.BucketV2(`${name}-bucket`, {
            tags,
        }, { parent: this });

        new aws.s3.BucketVersioningV2(`${name}-bucket-versioning`, {
            bucket: this.bucket.id,
            versioningConfiguration: {
                status: "Enabled",
            },
        }, { parent: this });

        new aws.s3.BucketServerSideEncryptionConfigurationV2(`${name}-bucket-encryption`, {
            bucket: this.bucket.id,
            rules: [{
                applyServerSideEncryptionByDefault: {
                    sseAlgorithm: "AES256",
                },
            }],
        }, { parent: this });

        this.bucketPolicyBlock = new aws.s3.BucketPublicAccessBlock(`${name}-bucket-pab`, {
            bucket: this.bucket.id,
            blockPublicAcls: true,
            blockPublicPolicy: true,
            ignorePublicAcls: true,
            restrictPublicBuckets: true,
        }, { parent: this });

        /**
         * RDS subnet group
         */
        this.dbSubnetGroup = new aws.rds.SubnetGroup(`${name}-db-subnets`, {
            subnetIds: args.subnetIds,
            tags,
        }, { parent: this });

        /**
         * RDS PostgreSQL
         * - deletion protection enabled
         * - backups >= 7 days
         * - not publicly accessible
         */
        this.db = new aws.rds.Instance(`${name}-db`, {
            engine: "postgres",
            engineVersion: "15.4",
            instanceClass: dbInstanceClass,
            allocatedStorage: dbAllocatedStorage,
            dbSubnetGroupName: this.dbSubnetGroup.name,
            vpcSecurityGroupIds: args.vpcSecurityGroupIds,
            dbName: args.dbName || "appdb",
            username: args.dbUsername || "appuser",
            password: args.dbPassword,
            publiclyAccessible: false,
            deletionProtection: true,
            backupRetentionPeriod,
            skipFinalSnapshot: false,
            finalSnapshotIdentifier: `${name}-${environment}-final-snapshot`,
            storageEncrypted: true,
            multiAz,
            autoMinorVersionUpgrade: true,
            applyImmediately: false,
            tags,
        }, { parent: this });

        /**
         * IAM role for service accounts
         * - prod: least-privilege trust via OIDC if provided
         * - dev: can also use OIDC if provided
         */
        const assumeRolePolicy = pulumi
            .all([
                args.oidcProviderArn,
                args.oidcProviderUrl,
                args.k8sNamespace,
                args.k8sServiceAccountName,
            ])
            .apply(([providerArn, providerUrl, namespace, serviceAccountName]) => {
                if (providerArn && providerUrl && namespace && serviceAccountName) {
                    const cleanUrl = providerUrl.replace("https://", "");
                    return aws.iam.getPolicyDocumentOutput({
                        statements: [{
                            effect: "Allow",
                            actions: ["sts:AssumeRoleWithWebIdentity"],
                            principals: [{
                                type: "Federated",
                                identifiers: [providerArn],
                            }],
                            conditions: [
                                {
                                    test: "StringEquals",
                                    variable: `${cleanUrl}:sub`,
                                    values: [`system:serviceaccount:${namespace}:${serviceAccountName}`],
                                },
                                {
                                    test: "StringEquals",
                                    variable: `${cleanUrl}:aud`,
                                    values: ["sts.amazonaws.com"],
                                },
                            ],
                        }],
                    }).json;
                }

                // Fallback trust policy if OIDC is not provided.
                // Useful for bootstrapping, but OIDC is preferred.
                return aws.iam.getPolicyDocumentOutput({
                    statements: [{
                        effect: "Allow",
                        actions: ["sts:AssumeRole"],
                        principals: [{
                            type: "AWS",
                            identifiers: ["arn:aws:iam::${aws.getCallerIdentityOutput().accountId}:root"],
                        }],
                    }],
                }).json;
            });

        this.iamRole = new aws.iam.Role(`${name}-service-role`, {
            assumeRolePolicy,
            tags,
        }, { parent: this });

        /**
         * Least-privilege policy
         * - dev: simple scoped bucket access
         * - prod: no wildcard actions
         */
        const rolePolicyDoc = pulumi.all([this.bucket.arn]).apply(([bucketArn]) =>
            aws.iam.getPolicyDocumentOutput({
                statements: [
                    {
                        effect: "Allow",
                        actions: [
                            "s3:GetObject",
                            "s3:PutObject",
                            "s3:DeleteObject",
                        ],
                        resources: [`${bucketArn}/*`],
                    },
                    {
                        effect: "Allow",
                        actions: [
                            "s3:ListBucket",
                        ],
                        resources: [bucketArn],
                    },
                ],
            }).json
        );

        new aws.iam.RolePolicy(`${name}-service-policy`, {
            role: this.iamRole.id,
            policy: rolePolicyDoc,
        }, { parent: this });

        this.dbConnectionString = pulumi.interpolate`postgresql://${args.dbUsername || "appuser"}:${args.dbPassword}@${this.db.address}:${this.db.port}/${args.dbName || "appdb"}`;

        this.registerOutputs({
            bucketName: this.bucket.bucket,
            bucketArn: this.bucket.arn,
            dbEndpoint: this.db.address,
            dbPort: this.db.port,
            dbName: this.db.dbName,
            iamRoleArn: this.iamRole.arn,
            dbConnectionString: this.dbConnectionString,
        });
    }
}
```

