## File: `index.ts`

Example usage with stack config:

```ts
import * as pulumi from "@pulumi/pulumi";
import { AppPlatform } from "./infra/appPlatform";

const config = new pulumi.Config();

// Required config
const subnetIds = config.requireObject<string[]>("subnetIds");
const vpcSecurityGroupIds = config.requireObject<string[]>("vpcSecurityGroupIds");
const dbPassword = config.requireSecret("dbPassword");

// Optional config for IRSA/OIDC
const oidcProviderArn = config.get("oidcProviderArn");
const oidcProviderUrl = config.get("oidcProviderUrl");
const k8sNamespace = config.get("k8sNamespace") || "default";
const k8sServiceAccountName = config.get("k8sServiceAccountName") || "app-sa";

const app = new AppPlatform("app", {
    subnetIds,
    vpcSecurityGroupIds,
    dbPassword,
    dbName: "appdb",
    dbUsername: "appuser",
    oidcProviderArn,
    oidcProviderUrl,
    k8sNamespace,
    k8sServiceAccountName,
    tags: {
        Project: "canonical-webapp",
    },
});

export const bucketName = app.bucket.bucket;
export const dbEndpoint = app.db.address;
export const iamRoleArn = app.iamRole.arn;
export const dbConnectionString = app.dbConnectionString;
```

